# id: (chinese, style name, years, background, history, [feats], fictional?)
B={
'liubei':('劉備','Xuande','161–223',"A distant descendant of the Han imperial house who sold straw sandals and mats as a boy in Zhuo.","He rose fighting the Yellow Turbans and spent twenty years drifting between warlords. After allying with Sun Quan at Red Cliffs he took Jingzhou, then Yi province, and in 221 proclaimed himself emperor of Shu Han. He died at Baidicheng after his defeat at Xiaoting.",["Peach Garden Oath with Guan Yu and Zhang Fei (novel)","Three visits to Zhuge Liang's cottage","Founded the Shu Han dynasty in 221"]),
'guanyu':('關羽','Yunchang','?–220',"A fugitive from Hedong who joined Liu Bei in Zhuo and stayed at his side for over thirty years.","Briefly serving Cao Cao in 200, he cut down Yan Liang at Baima, then returned to Liu Bei. He guarded Jingzhou and in 219 drowned Yu Jin's army at Fancheng, but Lü Meng seized Jingzhou behind him and he was captured and executed by Wu.",["Slew Yan Liang at Baima","Flooded the Seven Armies at Fancheng","Later worshipped as Guan Di, god of war and loyalty"]),
'zhangfei':('張飛','Yide','?–221',"A butcher and wine-seller of Zhuo, Liu Bei's sworn brother.","At Changban in 208 he held a bridge with twenty riders and scared off Cao Cao's pursuit. He won Yi province's old general Yan Yan over by sparing him and beat Zhang He at Baxi. In 221 he was murdered in his sleep by two of his own officers.",["Held Changban Bridge","Spared and won over Yan Yan","Defeated Zhang He at Baxi"]),
'zhaoyun':('趙雲','Zilong','?–229',"From Changshan; he left Gongsun Zan to follow Liu Bei.","At Changban he rode through Cao Cao's army to save the infant Liu Shan and Lady Gan. Later he used an empty-camp ruse at the Han River and led the only orderly retreat of the first Northern Expedition.",["Rescued Liu Shan at Changban","Empty-camp ruse at the Han River","One of the Five Tiger Generals"]),
'zhugeliang':('諸葛亮','Kongming','181–234',"A recluse farming at Longzhong, nicknamed the Sleeping Dragon.","He gave Liu Bei the Longzhong Plan in 207, forged the alliance with Wu before Red Cliffs and became chancellor of Shu. He pacified the south and led five Northern Expeditions against Wei before dying in camp at the Wuzhang Plains.",["Longzhong Plan to divide the realm in three","Won Wu's alliance before Red Cliffs","Wooden oxen and gliding horses for supply"]),
'mizhu':('糜竺','Zizhong','?–221',"Heir to a rich merchant family of Donghai with ten thousand servants.","When Liu Bei lost Xu province in 196, Mi Zhu gave him his sister, gold and two thousand servants. He served as Liu Bei's envoy and was honoured above every other official, but fell ill with shame after his brother Mi Fang betrayed Guan Yu.",["Funded Liu Bei's army when it was destitute","Married his sister to Liu Bei","Highest-ranked minister of Shu"]),
'sunqian':('孫乾','Gongyou','?–c.215',"A scholar of Beihai recommended by the great teacher Zheng Xuan.","He was Liu Bei's diplomat for years, carrying messages to Yuan Shao and Liu Biao.",["Envoy to Yuan Shao","Envoy to Liu Biao","Served from the Xu province days"]),
'jianyong':('簡雍','Xianhe','?–?',"Liu Bei's boyhood friend from Zhuo.","Easy-going and witty, he sprawled on couches even before Liu Bei. In 214 he talked Liu Zhang into surrendering Chengdu.",["Lifelong friend of Liu Bei","Persuaded Liu Zhang to surrender","Famous joker of the Shu court"]),
'caocao':('曹操','Mengde','155–220',"Grandson by adoption of a palace eunuch, from Pei.","He raised troops against Dong Zhuo, took the Han emperor under his protection in 196 and crushed Yuan Shao at Guandu in 200 to unite the north. His drive south ended in fire at Red Cliffs in 208. He became King of Wei and was a fine poet.",["Victory at Guandu","Military farming colonies (tuntian)","Poet of 'Short Song Style'"]),
'xuchu':('許褚','Zhongkang','?–?',"A giant from Qiao who led village militia and once dragged a bandit's ox backwards by its tail.","He became Cao Cao's bodyguard, the 'Tiger Fool'. At Tong Pass he shielded Cao Cao with a saddle while poling the boat across the Wei River under Ma Chao's arrows.",["Saved Cao Cao at Tong Pass","Commanded the Tiger Guard","Dragged an ox by its tail"]),
'caoren':('曹仁','Zixiao','168–223',"Cao Cao's cousin, wild in youth, later a model general.","After Red Cliffs he held Jiangling against Zhou Yu for a year, and in 219 held Fancheng against Guan Yu until relief came.",["Rode out to rescue Niu Jin at Jiangling","Defended Fancheng","Rose to Grand Marshal"]),
'xiahoudun':('夏侯惇','Yuanrang','?–220',"Cao Cao's kinsman, who killed a man for insulting his teacher at fourteen.","He lost his left eye to an arrow fighting Lü Bu. Later he dammed rivers to farm land, worked in the fields himself, and became Cao Cao's most trusted general.",["Lost an eye fighting Lü Bu","Built dams for farming","General-in-Chief of Wei"]),
'xunyu':('荀彧','Wenruo','163–212',"A Yingchuan noble praised as 'a talent to assist a king'.","Cao Cao's chief strategist, he urged taking in the emperor and held Juancheng when Lü Bu struck. He opposed Cao Cao becoming duke and died soon after.",["Advised welcoming Emperor Xian","Held Juancheng against Lü Bu","Recommended Guo Jia and many others"]),
'xiahouyuan':('夏侯淵','Miaocai','?–219',"Cao Cao's kinsman, famed for lightning marches.","'Three days, five hundred li; six days, a thousand.' He conquered Liang province but was killed by Huang Zhong at Mount Dingjun.",["Lightning marches","Pacified Liang and the Qiang","Fell at Mount Dingjun"]),
'manchong':('滿寵','Boning','?–242',"A strict magistrate who did not spare the powerful.","He held Runan, stood by Cao Ren at Fancheng in 219 and later built and held Hefei's new fortress against Sun Quan.",["Vowed to die with Fancheng","Built Hefei New Fortress","Repelled Sun Quan's attacks"]),
'zhangliao':('張遼','Wenyuan','169–222',"A frontier officer who served Ding Yuan, Dong Zhuo and Lü Bu before Cao Cao.","At Xiaoyao Ford in 215 he charged Sun Quan's army with 800 men and nearly captured him. In Wu, crying children were hushed with his name.",["Xiaoyao Ford","Killed the Wuhuan chief Tadun","One of Wei's Five Elite Generals"]),
'lidian':('李典','Mancheng','?–?',"A bookish general from a powerful clan.","At Bowang he warned of Liu Bei's ambush and rescued Xiahou Dun. At Hefei he set aside a feud with Zhang Liao to fight beside him.",["Rescued Xiahou Dun at Bowang","Defended Hefei","Moved his clan to Ye to serve Cao Cao"]),
'yujin':('于禁','Wenze','?–221',"Once the strictest, most disciplined of Cao Cao's generals.","In 219 his army was drowned by floods at Fancheng and he surrendered to Guan Yu, a disgrace that haunted him to his death.",["Kept order during Wancheng's rout","Five Elite Generals of Wei","Surrendered at Fancheng"]),
'yuejin':('樂進','Wenqian','?–218',"Small in build but fearless.","He was often first up the walls in sieges and garrisoned Xiangyang against Guan Yu.",["First up the walls, many times","Garrisoned Xiangyang","One of Wei's Five Elite Generals"]),
'sunquan':('孫權','Zhongmou','182–252',"Younger brother of Sun Ce, who left him the south at eighteen.","He chose war at Red Cliffs, later took Jingzhou from Guan Yu and in 229 declared himself emperor of Wu, ruling for over fifty years.",["Allied with Liu Bei at Red Cliffs","Took Jingzhou in 219","Founded the state of Wu"]),
'zhangzhao':('張昭','Zibu','156–236',"A senior scholar to whom Sun Ce entrusted his young brother.","He ran Wu's government and urged surrender before Red Cliffs, but remained Sun Quan's stern, respected elder.",["Guardian of the young Sun Quan","Ran Wu's civil government","Famously blunt adviser"]),
'zhouyu':('周瑜','Gongjin','175–210',"Sun Ce's sworn friend from Lujiang, called 'Handsome Zhou'.","He married Xiao Qiao, commanded Wu's fleet at Red Cliffs and burned Cao Cao's ships. He took Jiangling in 209 but died the next year at 36. 'If the tune is wrong, Master Zhou looks round.'",["Fire attack at Red Cliffs","Took Jiangling","Master musician"]),
'ganning':('甘寧','Xingba','?–?',"A river pirate who wore bells on his belt so people knew he was coming.","Joining Sun Quan, he raided Cao Cao's camp at Ruxu at night with a hundred men and lost none. He saved Sun Quan at Xiaoyao Ford.",["Night raid at Ruxu","Saved Sun Quan at Xiaoyao","Former pirate of the Yangtze"]),
'taishici':('太史慈','Ziyi','166–206',"A Donglai archer famed for his loyalty and his bow.","He fought Sun Ce in single combat at Shenting, then joined him. In history he died in 206; here he still fights for Wu.",["Duel with Sun Ce at Shenting","Broke out of Beihai to fetch help","Master archer"]),
'zhoutai':('周泰','Youping','?–?',"A river man of Jiujiang.","He shielded young Sun Quan at Xuancheng, taking twelve wounds. Sun Quan later had him strip and counted his scars before the officers.",["Saved Sun Quan at Xuancheng","Wounds counted at a banquet","Commanded at Ruxu"]),
'lusu':('魯肅','Zijing','172–217',"A wealthy man who gave Zhou Yu a whole granary of rice.","He proposed a three-way division of the realm, championed the alliance with Liu Bei, lent Jingzhou and succeeded Zhou Yu.",["Tripod plan for Wu","Pushed for war at Red Cliffs","Single-sword meeting with Guan Yu"]),
'huanggai':('黃蓋','Gongfu','?–?',"A veteran who had served Sun Jian since the beginning.","At Red Cliffs he faked a defection and sailed fire-ships into Cao Cao's fleet.",["Fire-ships at Red Cliffs","Feigned surrender to Cao Cao","Veteran of three Sun lords"]),
'lumeng':('呂蒙','Ziming','178–220',"A rough soldier who took up study at Sun Quan's urging.","'No longer the Ah-Meng of Wu', he took Jingzhou in 219 by hiding soldiers in merchant boats dressed in white.",["Took Jingzhou with white-clad soldiers","Captured Guan Yu","A soldier who became a scholar"]),
'sunshangxiang':('孫夫人','Shangxiang','?–?',"Sun Quan's spirited younger sister, the 'bow-waist princess'.","She married Liu Bei in 209 and kept a hundred armed maids; even Liu Bei was wary. She returned to Wu around 211. Her name Shangxiang comes from opera.",["Married Liu Bei","Guarded by armed maids","Skilled with weapons"]),
'daqiao':('大喬','','?–?',"Elder of the two Qiao sisters of Wan, famed beauties.","When Sun Ce took Wan in 199 he married her, while her sister wed Zhou Yu. Legend says Cao Cao built the Bronze Sparrow Terrace dreaming of them.",["Wife of Sun Ce","One of the Two Qiaos","Celebrated in Du Mu's poem"]),
'xiaoqiao':('小喬','','?–?',"Younger of the Qiao sisters of Wan.","She married Zhou Yu in 199. In the novel Zhuge Liang goads Zhou Yu into war by hinting that Cao Cao wants the Qiaos.",["Wife of Zhou Yu","One of the Two Qiaos","Spark of Zhou Yu's anger in the novel"]),
'diaochan':('貂蟬','','fictional',"A singer in the household of the minister Wang Yun.","In the novel she was promised to both Lü Bu and Dong Zhuo, turning them against each other until Lü Bu killed the tyrant in 192. She is one of China's Four Beauties.",["Chain stratagem against Dong Zhuo","One of the Four Beauties","Here she serves Shu"],1),
'huangyueying':('黃月英','','?–?',"Daughter of the Jingzhou scholar Huang Chengyan, said to be plain but brilliant.","She married Zhuge Liang. Later legend credits her with inventions and with teaching her husband. Her personal name comes from folklore.",["Wife of Zhuge Liang","Legendary inventor","Daughter of Huang Chengyan"]),
'guanyinping':('關銀屏','','legend',"Guan Yu's daughter.","History records only that Sun Quan asked for her hand for his son and Guan Yu rudely refused. Folk tales name her Yinping and send her to fight in the south.",["Refused marriage to Sun Quan's son","Folk heroine of Yunnan","Daughter of Guan Yu"],1),
'zhurong':('祝融夫人','','fictional',"Wife of the Nanman king Meng Huo, said to descend from the fire god.","In the novel she rode into battle throwing flying knives and captured two Shu generals.",["Flying knives","Captured Zhang Ni and Ma Zhong","Queen of the Nanman"],1),
'caiwenji':('蔡琰','Wenji','c.177–?',"Daughter of the great scholar Cai Yong.","Carried off by the Xiongnu, she lived twelve years in the north until Cao Cao ransomed her. She recited four hundred of her father's lost texts from memory.",["Recovered her father's lost writings","'Poem of Grief and Indignation'","Ransomed by Cao Cao"]),
'zhenji':('甄夫人','','183–221',"A noblewoman of Zhongshan, wife of Yuan Xi.","When Ye fell in 204, Cao Pi took her as wife; she bore the future emperor Cao Rui but fell from favour and was ordered to die. Legend ties her to Cao Zhi's 'Nymph of the Luo River'.",["Mother of Emperor Cao Rui","Famed beauty of the north","Linked to the Luo River nymph"]),
'zhangchunhua':('張春華','','189–247',"Wife of Sima Yi.","When a maid saw Sima Yi, who was faking illness to avoid Cao Cao, drying his books in the rain, Zhang Chunhua killed her to keep the secret. She was mother of Sima Shi and Sima Zhao.",["Guarded Sima Yi's secret","Mother of the Jin founders' line","Feared even by Sima Yi"]),
'ladygan':('甘夫人','','?–c.210',"Liu Bei's consort from Pei, famous for jade-white skin.","She was saved by Zhao Yun at Changban and was mother of Liu Shan. She was honoured as empress after death.",["Mother of Liu Shan","Saved at Changban","Posthumous empress"]),
'ladymi':('糜夫人','','?–?',"Sister of Mi Zhu, married to Liu Bei in 196.","In the novel, wounded at Changban, she handed baby Liu Shan to Zhao Yun and threw herself into a well rather than slow him.",["Married Liu Bei in his darkest year","Sacrifice at Changban (novel)","Sister of Mi Zhu and Mi Fang"]),
'hanxuan':('韓玄','','?–?',"Administrator of Changsha under Liu Biao.","He submitted to Liu Bei in 209. In the novel he is a cruel lord killed by Wei Yan.",["Lord of Changsha","Master of Huang Zhong","Overthrown by Wei Yan (novel)"]),
'huangzhong':('黃忠','Hansheng','?–220',"A veteran of Nanyang who served Liu Biao's son in Changsha.","Joining Liu Bei in his sixties, he killed Xiahou Yuan at Mount Dingjun in 219. In the novel he spares Guan Yu and shoots the tassel off his helmet.",["Slew Xiahou Yuan at Dingjun","One of the Five Tiger Generals","The old general who never grew old"]),
'weiyan':('魏延','Wenchang','?–234',"A bold soldier who rose from the ranks.","Liu Bei made him governor of Hanzhong over Zhang Fei. He proposed a daring raid through the Ziwu Valley, and after Zhuge Liang's death was killed in a feud with Yang Yi.",["Governor of Hanzhong","Ziwu Valley plan","Fierce vanguard general"]),
'jinxuan':('金旋','Yuanji','?–209',"Administrator of Wuling.","He fell when Liu Bei took the southern commanderies; the novel has him shot by his own officer Gong Zhi.",["Lord of Wuling","Father of Jin Yi","Fell in 209"]),
'gongzhi':('鞏志','','fictional',"An officer of Wuling.","In the novel he urged Jin Xuan to surrender, then shot him and gave the city to Liu Bei.",["Surrendered Wuling to Liu Bei","Shot his own lord (novel)","Made Wuling administrator"],1),
'liudu':('劉度','','?–?',"Administrator of Lingling.","He surrendered to Liu Bei in 209 and was allowed to keep his post.",["Lord of Lingling","Surrendered to Liu Bei","Father of Liu Xian"]),
'xingdaorong':('邢道榮','','fictional',"A boastful axe-wielding general of Lingling.","In the novel he claimed the courage of ten thousand men, was beaten by Zhang Fei and killed by Zhao Yun.",["Giant battle-axe","Boasted of 10,000 men's courage","Lingling's champion (novel)"],1),
'zhaofan':('趙範','','?–?',"Administrator of Guiyang.","He offered his widowed sister-in-law to Zhao Yun, who refused, then surrendered Guiyang.",["Lord of Guiyang","Tried to marry off his sister-in-law","Surrendered to Liu Bei"]),
'chenying':('陳應','','fictional',"An officer of Guiyang.","In the novel he fought Zhao Yun with a flying fork and was captured.",["Flying fork","Plotted false surrender","Captured by Zhao Yun (novel)"],1),
}
